<?php
// build/review/whitelist_conflicts.php — the "votes vs plausibility" review sheet.
//
// Joins the fleet whitelist votes (all-extension.csv) against Sheet A membership,
// the C/E whitelists and the domain ledger, and writes
// state/review/whitelist-conflicts.json for HUMAN review. Machine-generated,
// regenerated by extension.yml after every fleet pull — never hand-edited;
// resolutions go into the Sheets (remove from A, or add to G), not into this file.
//
// Flags:
//   sheet-a-conflict  domain is in Sheet A (your popup curation) AND whitelisted —
//                     two authorities disagree; arbitrate per domain.
//   high-votes        ≥ HIGH_VOTES votes and NOT a Sheet A conflict — check that the
//                     count is proportional to plausible deliberate human use
//                     (a gibberish domain outranking major sites = gamed funnel).
//   ok                nothing suspicious on this heuristic; listed for completeness.

declare(strict_types=1);
ini_set('memory_limit', '2048M');

$ROOT = dirname(__DIR__, 2);
const HIGH_VOTES = 500;

function domains(string $path): array
{
    $arr = is_file($path) ? json_decode((string) file_get_contents($path), true) : null;
    return is_array($arr) ? array_fill_keys(array_map('strval', $arr), true) : [];
}

$votes = [];
$csv = $ROOT . '/sources/extension/whitelist/raw/all-extension.csv';
if (is_file($csv)) {
    foreach (array_slice(file($csv, FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES), 1) as $line) {
        [$d, $c] = array_pad(explode(',', $line, 2), 2, '0');
        if ($d !== '') $votes[$d] = (int) $c;
    }
}
$sheetA = domains($ROOT . '/sources/gsheet/popup.json');
$wlC    = domains($ROOT . '/sources/gsheet/default-whitelist.json');
$wlE    = domains($ROOT . '/sources/gsheet/manual-whitelist.json');
$ledger = is_file($ROOT . '/state/domain-ledger.json')
    ? (json_decode((string) file_get_contents($ROOT . '/state/domain-ledger.json'), true) ?: [])
    : [];

$universe = $votes;
foreach ($sheetA as $d => $_) if (isset($wlC[$d]) || isset($wlE[$d])) $universe[$d] ??= 0;

$rows = [];
foreach ($universe as $d => $_) {
    $via = [];
    if (isset($votes[$d])) $via[] = 'fleet';
    if (isset($wlC[$d]))   $via[] = 'sheet-C';
    if (isset($wlE[$d]))   $via[] = 'sheet-E';
    $inA = isset($sheetA[$d]);
    $flag = $inA ? 'sheet-a-conflict' : (($votes[$d] ?? 0) >= HIGH_VOTES ? 'high-votes' : 'ok');
    $rows[] = [
        'domain'          => $d,
        'votes'           => $votes[$d] ?? 0,
        'whitelisted_via' => $via,
        'in_sheet_a'      => $inA,
        'ledger'          => isset($ledger[$d])
            ? ['status' => $ledger[$d]['st'], 'sources' => $ledger[$d]['s'], 'last_ok' => $ledger[$d]['lo']]
            : null,
        'flag'            => $flag,
    ];
}
usort($rows, fn($a, $b) => [$a['flag'] === 'ok' ? 1 : 0, -$a['votes'], $a['domain']]
                       <=> [$b['flag'] === 'ok' ? 1 : 0, -$b['votes'], $b['domain']]);

$out = [
    'generated'  => gmdate('Y-m-d H:i') . ' UTC',
    'how_to_use' => 'Per flagged domain decide: Sheet A was wrong -> remove it from Sheet A; or the votes are gamed -> add the domain to Sheet G (omit-from-whitelist). This file is regenerated — record decisions in the Sheets only.',
    'counts'     => [
        'rows'             => count($rows),
        'sheet_a_conflict' => count(array_filter($rows, fn($r) => $r['flag'] === 'sheet-a-conflict')),
        'high_votes'       => count(array_filter($rows, fn($r) => $r['flag'] === 'high-votes')),
    ],
    'rows' => $rows,
];

@mkdir($ROOT . '/state/review', 0755, true);
$path = $ROOT . '/state/review/whitelist-conflicts.json';
file_put_contents($path . '.tmp', json_encode($out, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES) . "\n");
rename($path . '.tmp', $path);
echo "state/review/whitelist-conflicts.json — {$out['counts']['rows']} rows · "
   . "{$out['counts']['sheet_a_conflict']} sheet-A conflicts · {$out['counts']['high_votes']} high-vote reviews\n";
